ee:message.ee:set-payload:
%dw 2.0
output application/xml
ns soapenv http://schemas.xmlsoap.org/soap/envelope/
ns mus http://music.soa.itmo.ru/
var q = attributes.queryParams default {}
fun arr(v) = if (v is Array) v else if (v is String) [v] else []
var sorts   = arr(q.sort)   filter ((s) -> s != null and s != "")
var filters = arr(q.filter) filter ((f) -> f != null and f != "")
---
soapenv#Envelope: {
  soapenv#Header: {},
  soapenv#Body: {
    mus#ListMusicBands: {
      (sort: sorts) if (sizeOf(sorts) > 0),
      (page: (q.page as Number)) if (q.page? and q.page != ""),
      (size: (q.size as Number)) if (q.size? and q.size != ""),
      (filter: filters) if (sizeOf(filters) > 0)
    }
  }
}

%dw 2.0
output application/xml
ns soap http://schemas.xmlsoap.org/soap/envelope/
ns ns2 http://music.soa.itmo.ru/
---
if (payload.soap#Envelope.soap#Body.soap#Fault?) 
  // SOAP Fault detected - extract error info
  do {
    var faultDetail = payload.soap#Envelope.soap#Body.soap#Fault.detail.ns2#error
    var errorCode = faultDetail.code as Number default 500
    var errorMessage = faultDetail.message default "Internal Server Error"
    ---
    {
      error: {
        code: errorCode,
        message: errorMessage
      }
    }
  }
else 
  // Success response - extract music bands list
  { musicBands: payload.soap#Envelope.soap#Body.ns2#ListMusicBandsResponse.musicBands }

%dw 2.0
output application/xml
---
{
  error: {
    code: 500,
    message: (error.description default "Internal Server Error")
  }
}

%dw 2.0
output application/xml
ns soapenv http://schemas.xmlsoap.org/soap/envelope/
ns mus http://music.soa.itmo.ru/
---
soapenv#Envelope: {
  soapenv#Header: {},
  soapenv#Body: {
    mus#GetMusicBandById: {
      id: attributes.uriParams.id
    }
  }
}

%dw 2.0
output application/xml
ns soap http://schemas.xmlsoap.org/soap/envelope/
ns ns2 http://music.soa.itmo.ru/
---
if (payload.soap#Envelope.soap#Body.soap#Fault?) 
  do {
    var faultDetail = payload.soap#Envelope.soap#Body.soap#Fault.detail.ns2#error
    var errorCode = faultDetail.code as Number default 500
    var errorMessage = faultDetail.message default "Internal Server Error"
    ---
    {
      error: {
        code: errorCode,
        message: errorMessage
      }
    }
  }
else 
  do {
    var band = payload.soap#Envelope.soap#Body.ns2#GetMusicBandByIdResponse.musicBandAllSchema
    ---
    {
      musicBandAllSchema: {
        (band mapObject ((value, key) -> (key): value))
      }
    }
  }

%dw 2.0
output application/xml
---
{
  error: {
    code: 500,
    message: (error.description default "Internal Server Error")
  }
}

